CREATE TABLE IF NOT EXISTS realtor_outreach (id uuid default gen_random_uuid() primary key, name text not null, email text not null, city text, agency text, website text, status text default 'pending' check (status in ('pending', 'sent', 'replied', 'listed')), sent_at timestamptz, notes text, created_at timestamptz default now()); ALTER TABLE realtor_outreach ENABLE ROW LEVEL SECURITY; DROP POLICY IF EXISTS "Admin full access" ON realtor_outreach; CREATE POLICY "Admin full access" ON realtor_outreach FOR ALL USING (true);
